import{_ as e,o as a,c as o,aa as r}from"./chunks/framework.BAs_AphD.js";const i="/buildary-help-preview/academy/img/ciselniky/02.webp",l="/buildary-help-preview/media/cs/tickets/pravidla2.png",n="/buildary-help-preview/media/cs/tickets/nove_pravidlo2.png",s="/buildary-help-preview/media/cs/tickets/stitky2.png",c=JSON.parse('{"title":"Kategorie, štítky a pravidla","description":"","frontmatter":{"title":"Kategorie, štítky a pravidla","wiki":"cs:tickets:rules"},"headers":[],"relativePath":"tickets/rules.md","filePath":"tickets/rules.md","lastUpdated":1794209661000}'),d={name:"tickets/rules.md"};function k(p,t,v,u,y,g){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="kategorie-stitky-a-pravidla" tabindex="-1">Kategorie, štítky a pravidla <a class="header-anchor" href="#kategorie-stitky-a-pravidla" aria-label="Permalink to &quot;Kategorie, štítky a pravidla&quot;">​</a></h1><p>Číselníky úkolů přizpůsobíte stavbě: kategoriemi a štítky úkoly třídíte, pravidla za vás při zadání úkolu doplní Řešitele a Schvalovatele.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/ciselniky">Upravit kategorie a štítky úkolů</a> v Akademii.</p><h2 id="kde-ciselniky-najdete" tabindex="-1">Kde číselníky najdete <a class="header-anchor" href="#kde-ciselniky-najdete" aria-label="Permalink to &quot;Kde číselníky najdete&quot;">​</a></h2><p>Otevřete <strong>Nastavení stavby</strong> a záložku <strong>Číselníky - Management úkolů</strong>. Upravovat je smí ten, kdo má na stavbě kompetenci <strong>Administrace stavby</strong> – viz <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</p><table tabindex="0"><thead><tr><th>Záložka</th><th>K čemu slouží</th></tr></thead><tbody><tr><td><strong>Kategorie úkolů</strong></td><td>Základní rozdělení úkolů podle toho, čeho se týkají. Každý úkol má jednu kategorii.</td></tr><tr><td><strong>Pravidlo Řešitelé</strong></td><td>Podmínky, za kterých se u nového úkolu samo vyplní pole <strong>Řešitelé</strong>.</td></tr><tr><td><strong>Pravidlo Schvalovatelé</strong></td><td>Podmínky, za kterých se u nového úkolu samo vyplní pole <strong>Schvalovatelé</strong>.</td></tr><tr><td><strong>Štítky</strong></td><td>Vlastní označení úkolů podle potřeb stavby. Úkol může mít štítků víc.</td></tr></tbody></table><h2 id="kategorie-ukolu" tabindex="-1">Kategorie úkolů <a class="header-anchor" href="#kategorie-ukolu" aria-label="Permalink to &quot;Kategorie úkolů&quot;">​</a></h2><p>Číselník kategorií je předem vyplněný – například <strong>BOZP, PO a ŽP</strong>, <strong>Kontrolní dny a jednání</strong>, <strong>Kontroly a zkoušky</strong>, <strong>Neshody, vady a nedodělky</strong> nebo <strong>Předání a převzetí</strong>. Kategorii vybírá Zadavatel u nového úkolu a později ji může změnit v detailu úkolu.</p><figure class="shot" style="--w:760px;"><img src="'+i+'" alt="Záložka Kategorie úkolů s názvy kategorií a jejich zkratkami" loading="lazy"></figure><ul><li>Novou kategorii přidáte tlačítkem <strong>Přidat</strong>, stávající upravíte ikonou tužky nebo smažete ikonou koše.</li><li><strong>Zkratka</strong> má dvě písmena. Zobrazuje se v ikoně kategorie v seznamu úkolů a v Kanbanu, proto ji volte tak, aby byla srozumitelná.</li><li>Kategorii, která je už u některého úkolu, smazat nejde. Můžete ji jen upravit.</li></ul><h2 id="pravidla-pro-resitele-a-schvalovatele" tabindex="-1">Pravidla pro Řešitele a Schvalovatele <a class="header-anchor" href="#pravidla-pro-resitele-a-schvalovatele" aria-label="Permalink to &quot;Pravidla pro Řešitele a Schvalovatele&quot;">​</a></h2><p>Pravidlo určuje, kdo se má u úkolu automaticky objevit jako Řešitel nebo Schvalovatel. Hodí se tam, kde je jasně dané, kdo za co odpovídá – například vady na komunikacích řeší vždy tentýž mistr. Pravidla platí při zadávání úkolu na webu i v mobilní aplikaci.</p><p>Pravidla pro Řešitele zakládáte na záložce <strong>Pravidlo Řešitelé</strong>, pro Schvalovatele na záložce <strong>Pravidlo Schvalovatelé</strong>. Obě fungují stejně.</p><figure class="shot" style="--w:760px;"><img src="'+l+'" alt="Záložka Pravidlo Řešitelé se dvěma pravidly, jejich pořadím, kategoriemi a částmi stavby" loading="lazy"></figure><h3 id="zalozit-pravidlo" tabindex="-1">Založit pravidlo <a class="header-anchor" href="#zalozit-pravidlo" aria-label="Permalink to &quot;Založit pravidlo&quot;">​</a></h3><p>Klikněte na <strong>Přidat</strong> a vyplňte:</p><table tabindex="0"><thead><tr><th>Pole</th><th>Význam</th></tr></thead><tbody><tr><td><strong>Řešitelé</strong> (nebo <strong>Schvalovatelé</strong>)</td><td>Jedna nebo víc osob, které pravidlo doplní. Vybíráte z členů projektového týmu – kdo v nabídce chybí, přidejte nejdřív do projektového týmu – viz <a href="/buildary-help-preview/diary/projectteam">Projektový tým: firmy a lidé</a>.</td></tr><tr><td><strong>Kategorie</strong></td><td>Kategorie úkolu, pro které pravidlo platí.</td></tr><tr><td><strong>Části stavby</strong></td><td>Části stavby, pro které pravidlo platí. Nabízí se části ze záložky <strong>Části stavby a výkresy</strong>.</td></tr><tr><td><strong>Výkresy</strong></td><td>Výkresy, pro které pravidlo platí. Volba <strong>Libovolné</strong> znamená jakýkoli výkres.</td></tr></tbody></table><p>Pravidel můžete založit, kolik potřebujete. Podmínky nemusíte vyplnit všechny – pravidlo může záviset třeba jen na kategorii. Jak části stavby a výkresy připravit, popisuje <a href="/buildary-help-preview/diary/projectparts">Části stavby a výkresy</a>.</p><h3 id="jak-se-podminky-vyhodnocuji" tabindex="-1">Jak se podmínky vyhodnocují <a class="header-anchor" href="#jak-se-podminky-vyhodnocuji" aria-label="Permalink to &quot;Jak se podmínky vyhodnocují&quot;">​</a></h3><ul><li>V jednom poli stačí, aby úkol odpovídal <strong>kterékoli</strong> vybrané hodnotě.</li><li>Mezi poli platí <strong>a zároveň</strong> – úkol musí odpovídat kategorii, části stavby i výkresu.</li><li>Pole, které pravidlo doplní, můžete u konkrétního úkolu dál změnit nebo doplnit o další osoby.</li></ul><figure class="shot" style="--w:420px;"><img src="'+n+'" alt="Okno Vytvoření pravidla s Řešiteli, kategoriemi, částmi stavby a výkresy" loading="lazy"></figure><div class="info custom-block"><p class="custom-block-title">Příklad</p><p>Pravidlo na obrázku má Řešitele Iva Černá a Tomáš Novák, kategorie <strong>Neshody, vady a nedodělky</strong> a <strong>Kontrolní dny a jednání</strong>, části stavby SO 02, SO 03 a SO 04 a výkresy <strong>Libovolné</strong>.</p><ul><li>Úkol v kategorii Neshody, vady a nedodělky na části SO 02: Řešitelé se doplní.</li><li>Úkol v kategorii Kontroly a zkoušky na části SO 02: kategorie neodpovídá, pravidlo se neuplatní.</li></ul></div><h3 id="poradi-pravidel" tabindex="-1">Pořadí pravidel <a class="header-anchor" href="#poradi-pravidel" aria-label="Permalink to &quot;Pořadí pravidel&quot;">​</a></h3><p>Pravidla jsou v seznamu seřazená podle pořadí. Pravidlo výš má přednost před pravidlem pod ním. Pořadí měníte šipkami na řádku pravidla, ikonou tužky pravidlo upravíte, ikonou koše smažete.</p><h2 id="stitky" tabindex="-1">Štítky <a class="header-anchor" href="#stitky" aria-label="Permalink to &quot;Štítky&quot;">​</a></h2><p>Štítky jsou vaše vlastní označení úkolů nad rámec kategorie – například podle profese nebo podzhotovitele. Číselník je na začátku prázdný.</p><figure class="shot" style="--w:760px;"><img src="'+s+'" alt="Záložka Štítky s barevnými štítky a jejich popisy" loading="lazy"></figure><ul><li>Štítek přidáte tlačítkem <strong>Přidat štítek</strong>. Zvolíte <strong>barvu</strong>, <strong>název</strong> a případně <strong>popis</strong>.</li><li>Barva pomáhá štítek v přehledech rychle rozpoznat.</li><li>U úkolu můžete vybrat jeden nebo víc štítků.</li><li>V seznamu úkolů se štítky zobrazí, když si do pohledu přidáte jejich sloupec, a podle nich pak úkoly filtrujete – viz <a href="/buildary-help-preview/tickets/task_grid">Seznam úkolů a filtry</a>.</li></ul>',28)])])}const m=e(d,[["render",k]]);export{c as __pageData,m as default};
